INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (85, 199, 'BOPP/BOPET Capacitor Film clear', '../upload/image/20180922/20180922164935_28525.jpg', '<p></p><p><span style="color:#009900;font-family:Verdana;font-size:16px;"><strong>BOPP/BOPET Capacitor Film clear</strong></span></p> <p></p><p><span style="color:#009900;font-family:Verdana;font-size:16px;">Polypropylene films BOPP Dielectric grade</span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;">1) Plain &amp; Film for making suitable for High / Extra High Voltage Capacitors</span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;">2) Plain &amp; Hazy Corona treated suitable for metalizing for making Metalized Film Capacitors)</span></p> <p><br/></p> <p><span style="color:#009900;font-family:Tahoma;font-size:16px;">1. BOPP capacitor film have two items, BOPP clear capacitor film and BOPP rough clear capacitor film.</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:16px;"> 1.)M-PP for metallized -film capacitors applications . </span><br/> <span style="color:#009900;font-family:Tahoma;font-size:16px;"> 2.)S-PP for foil-film capacitors applications . </span><br/> <span style="color:#009900;font-family:Tahoma;font-size:16px;"> The standard thickness range including: 3 ,4,5,6,7,8,9,10,12 microns .</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:16px;"> The standard tolerance thickness: +/-0.2 Um .</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:16px;"> The width range including: can slit any width(MM )upon the requirement. </span><br/> <span style="color:#009900;font-family:Tahoma;font-size:16px;"> The inner core : 3" (76MM)</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:16px;"> The outer core: 150-350 MM .</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:16px;"> BOPP Capacitor film included RPP BOPP capacitor film,RRPP BOPP capacitor film, Polypropylene metallized capacitor Film (Zn metallized film,zn/al BOPP capacitor film),capacitor foil film</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:16px;"> 2. BOPP rough clear capacitor film .</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:16px;"> 1.)R-PP : one side of rough capacitor film ( power capacitor use). </span><br/> <span style="color:#009900;font-family:Tahoma;font-size:16px;"> 2.)RR-PP: two sides of rough capacitor film . </span><br/> <span style="color:#009900;font-family:Tahoma;font-size:16px;"> The thickness range including: 6,7,8,9,10,12,18 microns .</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:16px;"> The width range including: can slit any width (MM) upon the requirement. </span><br/> <span style="color:#009900;font-family:Tahoma;font-size:16px;"> The inner core : 3" (76MM),6''(152MM)</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:16px;"> The outer core: 150-350 MM .</span><br/> <span style="color:#009900;font-family:Tahoma;font-size:16px;"> Features:1) single side corona treated for the Zn or Zn/Al metallized .</span></p> <p></p><table height="988" style="width:432.02pt;border-collapse:collapse;" width="576"> <tbody> <tr> <td class="et1" height="19" style="color:#000000;font-size:11pt;font-style:normal;font-weight:400;text-decoration:none;vertical-align:middle;" width="72"> <span style="color:#009900;font-family:Tahoma;font-size:16px;">Specification</span> </td> <td height="19"> </td> <td height="19"> </td> <td height="19"> </td> <td height="19"> </td> <td height="19"> </td> <td height="19"> </td> <td height="19"> </td> </tr> <tr> <td height="19"> </td> <td height="19"> </td> <td height="19"> </td> <td height="19"> </td> <td height="19"> </td> <td height="19"> </td> <td height="19"> </td> <td height="19"> </td> </tr> <tr> <td height="19"> </td> <td class="et2" height="19" style="text-align:center;color:#000000;font-size:11pt;font-style:normal;font-weight:400;te