INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (85, 252, 'Polypropylene safety capacitor film', '../upload/image/20180925/20180925232857_66233.jpg', '<p></p><div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span><span style="font-family:Tahoma;font-size:18px;"><strong>Polypropylene safety capacitor film</strong></span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span><span style="font-family:Tahoma;font-size:18px;">Features:</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-family:Tahoma;font-size:18px;"></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span><span style="font-family:Tahoma;font-size:18px;">The surface of film Vacuum metallized a thin electrode layer with appointed special designs , it comes true the integration of the three ,as capacitor dielectric, electrode and explosion-proof.</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span><span style="font-family:Tahoma;font-size:18px;">Do it like this , which realize a revolutionary progress of the explosion-proof mechanism.</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span><span style="font-family:Tahoma;font-size:18px;">It features electrode pattern being clear, innovative design, excellent explosion-proof performance, security and high reliability.</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span><span style="font-family:Tahoma;font-size:18px;">It used for manufacture blast-proof structure, medium and electrode material of blast-proof capacitor.</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span><span style="font-family:Tahoma;font-size:18px;">Film thickness: 2.5UM-15UM</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span><span style="font-family:Tahoma;font-size:18px;">Electrode design: grid-type, T type</span></span> </div>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (85, 254, 'BOPP clear rough film for capacitors', '../upload/image/20180925/20180925232838_79793.jpg', '<p></p><div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">BOPP clear rough film for capacitors</span><br/> </span><span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Features:</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Impulse a deep-rough treatment into single side or double sides on the surface of the film in order to form some certain concave ,then let the film be characteristic even roughness ,low dielectric loss, and high dielectric strength and good compatibility with kinds of Dipping Oil but with small Swelling.</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Mainly used for Baptist paper composite membrane oil medium or total capacitor dielectric film Baptist Oil: such as high-voltage capacitor and capacitor for electric induction heating system,etc.</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Specification:</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Thickness: 6UM—15UM</span></span> </div> <div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-w